INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('GS.SIGNIN', 'GUIDE', 'GENERAL', N'Sign in, choose your branch and role', N'How to sign in and start working in the right branch with the right role.', N'HOME.DASHBOARD', N'login log in sign in signin branch role select switch start dashboard', N'{"steps": ["Open the application and enter your Email and Password, then click Sign In (or press Enter). You sign in with your e-mail address, not a user name.", "If you work in more than one branch, choose the branch and press Enter or click Continue to Dashboard. Your last used branch is pre-selected.", "If you have more than one role, choose the role (arrow keys move between roles) and press Enter. The left side shows what the role can open.", "The Home page opens. The top bar shows the menus your role may use, the notification bell, your branch and your profile."], "prereq": [], "tips": ["Tick Remember me only on your own computer.", "You can switch branch or role any time from your profile menu (top right) without signing out.", "Too many wrong passwords lock the account for a while - wait, or use Forgot password?"], "next": ["HOME.DASHBOARD"]}', 0);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('GS.FORGOT', 'GUIDE', 'GENERAL', N'Forgot your password? Reset it by email', N'Get a reset link by email and set a new password without calling the administrator.', N'', N'forgot password reset link email change password locked', N'{"steps": ["On the sign-in screen click Forgot password?.", "Enter your user name or the email address on your account and click Send Reset Link.", "Open the email ''eCare360Plus+ - Reset your password'' and click Reset Password (the link works once, for 30 minutes).", "Type a new password twice (at least 8 characters, with a letter and a number) and click Reset Password.", "Sign in with the new password. You also get an email saying the password was changed."], "prereq": [], "tips": ["No email? Check Spam / Junk. Your user account must have an email address - ask the administrator to add it in User Master.", "Asking for a new link cancels the earlier ones."], "next": []}', 10);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('GS.CHANGEPWD', 'GUIDE', 'GENERAL', N'Change your password', N'Change the password of your own account.', N'', N'change password profile security', N'{"steps": ["Open your profile menu (your name, top right) and choose Change Password.", "Enter the current password, then the new password twice (8+ characters with a letter and a number).", "Click Save. Use the new password from your next sign-in."], "prereq": [], "tips": [], "next": []}', 20);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('GS.NAVIGATE', 'GUIDE', 'GENERAL', N'Find your way around', N'The top menus, the notification bell, help on every page and switching branch or role.', N'', N'menu navigation bell notification help question tone sound switch branch role', N'{"steps": ["The top bar holds the menus: Home, OPD, LAB, IPD, Master, Settings, Utility, Quality & Compliance and Reports. You only see what your role may open.", "Point at a menu to open it; menus with an arrow open a sub-menu (near the right edge it opens to the left).", "The bell shows notifications such as approval requests. New ones ring the bell, show a message and play a tone (turn the sound on/off with the speaker button inside the bell).", "Ask eMedi at the bottom right of Home, or Utility > Help Center, opens the AI Help Assistant - ask what to do next.", "Your profile menu (top right) has Change Password, Switch Branch, Switch Role and Sign Out."], "prereq": [], "tips": ["The branch badge (e.g. HO) shows which branch you are working in - bills and reports belong to it."], "next": []}', 30);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('SET.BRANCH', 'GUIDE', 'SETTINGS', N'Set up a new branch', N'Add a branch (centre) so it can bill, collect samples and report.', N'SETTINGS.BRANCHES,SETTINGS.HOSPITALSETTINGS', N'branch centre new branch head office HO setup', N'{"steps": ["Settings > Branch Master: click Add, enter the branch name, code, address and contact; mark exactly one branch as Head Office.", "Settings > Hospital Settings: choose the branch and fill the hospital name, address, logo, contact and the LAB / billing / printing options.", "Settings > Email Configuration: add the branch''s mail account (SMTP) and send a test email.", "Settings > User Master: give users access to the new branch (branch mapping) and the roles they work in.", "Masters: check rate lists and doctors apply to the branch."], "prereq": ["SETTINGS.COMPANIES"], "tips": [], "next": ["SETTINGS.SMTPCONFIG", "SETTINGS.USERS"]}', 40);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('SET.USER', 'GUIDE', 'SETTINGS', N'Create a user and give access', N'Add a staff member, map branches and roles, and set special flags.', N'SETTINGS.USERS', N'user staff add user create account login access role department pathologist technician', N'{"steps": ["Settings > User Master: click Add User; enter the e-mail first - it is the sign-in, must be unique in the whole application and is checked as you type (green = available); the user name is the e-mail. Then name and phone.", "Choose the branches the user works in and the role(s) in each branch.", "For LAB staff tick Lab Technician or Pathologist and choose the departments they may report (Department Access). Without this, Lab Reporting is not available to them.", "Save. The user signs in with the default password and changes it.", "If the user cannot open a page, check the role in Settings > Security > Role Permissions, or the user''s own extra permissions."], "prereq": ["SETTINGS.BRANCHES"], "tips": [], "next": ["SETTINGS.SECURITY.ROLEPERMISSIONS", "SETTINGS.SECURITY.EFFECTIVEPERMISSIONS"]}', 50);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('SET.PERMISSIONS', 'GUIDE', 'SETTINGS', N'Give a role access to pages and actions', N'Decide which pages a role may open and which actions (add, edit, approve, print...) it may use.', N'SETTINGS.SECURITY.ROLEPERMISSIONS,SETTINGS.SECURITY.USERPERMISSIONS,SETTINGS.SECURITY.EFFECTIVEPERMISSIONS,SETTINGS.SECURITY.MENUPAGES', N'permission role access rights menu missing page denied security grant', N'{"steps": ["Settings > Security > Role Permissions: choose the role.", "Tick the pages the role may open; inside a page tick the actions it may use (for example Approve, Print, Cancel).", "Save. Users of the role see the change at their next page load (menus refresh within a few minutes).", "To check one person, open Settings > Security > Effective Permissions and choose the user: it shows what they can really do and why."], "prereq": ["SETTINGS.USERS"], "tips": ["New screens are added without access for any role - give them to the right roles here.", "User Permissions add or remove a page for one user on top of the role."], "next": []}', 60);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('SET.SMTP', 'GUIDE', 'SETTINGS', N'Set up email for a branch', N'Bills, reports, password resets and campaigns are emailed with the branch''s mail account.', N'SETTINGS.SMTPCONFIG', N'email smtp mail configuration test email gmail outlook base url', N'{"steps": ["Settings > Email Configuration: click Add and choose the branch.", "Enter the SMTP host, port, SSL, sender email / display name, user name and password from your email provider.", "Enter the Application Base URL (the address users open the application with) - links in emails use it.", "Mark it Default and Active, save, then use Test Email to send yourself a message.", "Check Utility > Email Logs if an email did not arrive."], "prereq": ["SETTINGS.BRANCHES"], "tips": ["Password-reset emails always use the Head Office branch''s mail settings.", "Gmail / Office 365 often need an ''app password'' instead of the normal password."], "next": ["UTILITY.EMAILLOGS", "UTILITY.EMAILTEMPLATE"]}', 70);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('SET.HOSPITAL', 'GUIDE', 'SETTINGS', N'Hospital Settings: the rules of a branch', N'Name and logo on prints, billing and LAB options, approvals, printing and AI features.', N'SETTINGS.HOSPITALSETTINGS', N'hospital settings logo print a4 a5 page size ai features pathologist approval report email whatsapp', N'{"steps": ["Settings > Hospital Settings: open the branch.", "General: hospital name, address, phone, email, website and logo (printed on bills and reports).", "LAB: email / WhatsApp report delivery, pathologist approval required, bill print page size (A4 or A5 landscape) and other LAB rules.", "AI: Enable AI Features at Billing (Smart ID Scan, document check and test suggestions).", "Save. The changes apply to that branch at once."], "prereq": ["SETTINGS.BRANCHES"], "tips": [], "next": []}', 80);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('SET.APPROVALS', 'GUIDE', 'SETTINGS', N'Approvals: discounts and master changes', N'Decide who must approve discounts and changes to masters, and handle the requests.', N'SETTINGS.APPROVALMATRIX,UTILITY.APPROVALDASHBOARD', N'approval matrix discount approve reject request notification approver', N'{"steps": ["Settings > Approval Matrix: for each type (for example discount above a limit) choose the approver role / user and the limits.", "When a request needs approval the approver gets a notification (bell) and finds it in Utility > Approval Dashboard.", "The approver opens the request, checks it and clicks Approve or Reject with a remark.", "The person who asked is notified of the decision."], "prereq": [], "tips": [], "next": []}', 90);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('SET.LABFLOW', 'GUIDE', 'SETTINGS', N'Pathologist approval flow (report sign-off levels)', N'Set how many pathologists must sign a LAB report and who they are.', N'SETTINGS.LABAPPROVALFLOWS', N'pathologist approval flow levels sign off signatory', N'{"steps": ["Settings > Pathologist Approval Flow: choose the branch / department.", "Add the levels (for example Level 1 Senior Technician, Level 2 Pathologist) and the users for each level.", "Hospital Settings > LAB: switch on Pathologist approval required if reports must be signed from the Report Approval Dashboard.", "Pathologists then approve from LAB > Report Approval Dashboard."], "prereq": [], "tips": [], "next": ["LAB.PATHOLOGISTDASHBOARD"]}', 100);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('SET.LICENCE', 'GUIDE', 'SETTINGS', N'Licence', N'See the licence of this server and re-check it with the licence server.', N'SETTINGS.LICENSE', N'licence license expired validate otp renewal', N'{"steps": ["Settings > Licence shows the licence, its validity and the registered server.", "If the sign-in screen asks to re-validate, click Re-validate licence with the licence server and follow the OTP step if shown."], "prereq": [], "tips": [], "next": []}', 110);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('MAS.DOCTOR', 'GUIDE', 'MASTER', N'Add a doctor', N'Add consulting doctors (and referral doctors) used in OPD, LAB referrals and commissions.', N'MASTER.DOCTORS,MASTER.REFERRALDOCTORS,MASTER.DOCTORSPECIALITIES', N'doctor add doctor consultant speciality referral fee', N'{"steps": ["Master > General > Doctor Speciality Master: make sure the speciality exists.", "Master > General > Doctor Master: click Add; enter name, prefix (Dr.), gender, speciality, registration (licence) number, phone and email.", "Set consultation charges and the branches the doctor works in, then save.", "For OPD: assign a room (Room Doctor Assignment) and create the roster (OPD > Doctor Roster).", "Referral doctors who send patients are added in Referral Doctor Master."], "prereq": ["MASTER.DOCTORSPECIALITIES"], "tips": [], "next": ["MASTER.ROOMDOCTORASSIGNMENT", "OPD.DOCTORROSTER"]}', 120);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('MAS.TEST', 'GUIDE', 'MASTER', N'Add a LAB test (investigation)', N'Create a test with everything reporting and billing need.', N'MASTER.LABINVESTIGATIONS,MASTER.LABREFERENCERANGES', N'test investigation add test new test reference range normal range unit sample type tat', N'{"steps": ["Make sure the masters it uses exist: Department, Test Category / Sub Category, Sample Type, Unit and Method.", "Master > Lab Master > Investigation Master: click Add; enter code, name, department, category, sub category, sample type, unit, method and TAT (hours).", "Choose the reporting type (numeric, text / picklist, descriptive template, culture...).", "Save, then add normal ranges in Reference Range Master (by gender and age).", "Add the price in Rate List (B2C) - and in franchise / corporate rate lists for B2B.", "Optional: add it to a profile or package (Investigation Profile Master), a formula (Lab Formula Component) or a reflex rule."], "prereq": ["MASTER.LABTESTCATEGORIES", "MASTER.LABSAMPLETYPES", "MASTER.LAB_MASTER.LABUNITS", "MASTER.LABTESTMETHODS"], "tips": [], "next": ["MASTER.LABRATELISTB2C", "MASTER.LABINVESTIGATIONPROFILES"]}', 130);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('MAS.PROFILE', 'GUIDE', 'MASTER', N'Create a profile or package', N'Group tests that are booked together (Lipid Profile, health packages).', N'MASTER.LABINVESTIGATIONPROFILES', N'profile package panel group tests lipid health check', N'{"steps": ["Master > Lab Master > Investigation Profile Master: click Add.", "Choose the type (profile or package), enter code, name and price, and add the tests in the order they print.", "Save. Add the profile / package price in the rate lists.", "At booking, choosing the profile adds all its tests; reports print them together."], "prereq": ["MASTER.LABINVESTIGATIONS"], "tips": [], "next": ["MASTER.LABRATELISTB2C"]}', 140);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('MAS.RATELIST', 'GUIDE', 'MASTER', N'Prices: B2C, franchise and corporate rate lists', N'Set what walk-in patients, franchises and corporates pay for each test.', N'MASTER.LABRATELISTB2C,MASTER.LABRATELISTFRANCHISE,MASTER.LABRATELISTCORPORATE', N'price rate list mrp b2c b2b franchise corporate discount allowed', N'{"steps": ["Master > Lab Master > Rate List (B2C): set the price of each test / profile / package for walk-in patients and whether a discount is allowed.", "Rate List (Franchise): the price a franchise / collection centre pays (B2B).", "Rate List (Corporate): the price a corporate pays.", "Changes may need approval (Approval Matrix). Bills made after the change use the new price."], "prereq": ["MASTER.LABINVESTIGATIONS"], "tips": [], "next": []}', 150);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('MAS.REFLEX', 'GUIDE', 'MASTER', N'Reflex rules (suggest a follow-up test)', N'When a result meets a condition, Lab Reporting suggests a follow-up test to the pathologist.', N'MASTER.LABREFLEXRULES', N'reflex rule follow up test suggestion advise', N'{"steps": ["Master > Lab Master > Reflex Rules. Standard rules are added switched off - review and switch on the ones you use.", "To add a rule: choose the result test, the condition (greater than, between, flagged high, contains text...), the value and the test to suggest; add the reason.", "Save. Suggestions show on Lab Reporting Entry when AI features are on; the pathologist advises or dismisses them."], "prereq": ["MASTER.LABINVESTIGATIONS"], "tips": [], "next": ["LAB.LABREPORTING"]}', 160);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('MAS.MEMBERSHIP', 'GUIDE', 'MASTER', N'Membership plans and cards', N'Sell membership cards with benefits and points.', N'MASTER.MEMBERSHIPPLANS,MASTER.MEMBERSHIPCARDS', N'membership card plan points family redeem otp', N'{"steps": ["Master > General > Membership Plan Master: create the plan (price, validity, discount / points rules, family members).", "Master > General > Membership Cards: issue a card - search the patient by phone (an existing patient is filled in), add family members and collect payment.", "Send the card by email / WhatsApp. At billing the card''s discount applies and points can be redeemed with an OTP."], "prereq": [], "tips": [], "next": []}', 170);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('OPD.REGISTER', 'GUIDE', 'OPD', N'Register a new patient', N'Create the patient record (patient ID) used by OPD, LAB and IPD.', N'OPD.PATIENTREGISTRATION,MASTER.OPD', N'register patient new patient registration uhid patient id duplicate', N'{"steps": ["OPD > Patient Registration: search by phone first - the patient may already exist.", "Enter name, gender, date of birth (or age), phone, email and address; add an ID document if needed.", "Save. The patient gets a Patient ID (e.g. PHO2627000053) used everywhere.", "Continue to Service Booking to book a consultation, or to LAB booking for tests."], "prereq": [], "tips": ["Always search by phone before registering to avoid duplicates. Family members can share a phone."], "next": ["OPD.SERVICEBOOKING", "LAB.LABORDERBOOKING.B2CBOOKING"]}', 180);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('OPD.BOOK', 'GUIDE', 'OPD', N'Book a consultation or service and bill it', N'Book the doctor / service, take payment and give a token.', N'OPD.SERVICEBOOKING', N'appointment booking consultation opd bill token service slot fee', N'{"steps": ["OPD > Service Booking: find the patient (or register a new one).", "Choose the doctor, date and slot (from the doctor''s roster) and the service; the fee is filled in.", "Apply a discount if allowed (above the limit it needs approval) and collect payment (cash, card, UPI...).", "Save and print the bill. The patient gets a token and, if email is set up, a booking confirmation email."], "prereq": ["OPD.PATIENTREGISTRATION", "OPD.DOCTORROSTER", "MASTER.SERVICES"], "tips": [], "next": ["OPD.TOKENMANAGEMENT", "OPD.VITALS"]}', 190);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('OPD.ROSTER', 'GUIDE', 'OPD', N'Doctor roster (schedules and slots)', N'Set when each doctor sits, so appointments can be booked.', N'OPD.DOCTORROSTER', N'roster schedule slot doctor timing availability', N'{"steps": ["OPD > Doctor Roster: choose the doctor.", "Add the days and times, slot length and maximum patients; save.", "Leaves / holidays block booking for those days."], "prereq": ["MASTER.DOCTORS"], "tips": [], "next": ["OPD.SERVICEBOOKING"]}', 200);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('OPD.FLOW', 'GUIDE', 'OPD', N'Patient flow on the day: token, vitals, consultation', N'Move the patient from the waiting area to the doctor and out with a prescription.', N'OPD.TOKENMANAGEMENT,OPD.VITALS,OPD.DOCTORDASHBOARD,OPD.DASHBOARD', N'token queue vitals consultation doctor dashboard prescription emr follow up', N'{"steps": ["OPD > Token Management: call the next token; the patient goes to vitals.", "OPD > Patient Vitals: record BP, pulse, temperature, weight, SpO2...", "OPD > Doctor Dashboard: the doctor opens the patient, writes complaints, diagnosis, advises investigations and prescribes medicines, sets follow-up.", "Finish the consultation; the prescription can be printed and emailed (Prescription Delivery template)."], "prereq": ["OPD.SERVICEBOOKING"], "tips": [], "next": []}', 210);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('OPD.CLOSE', 'GUIDE', 'OPD', N'OPD day closing', N'Close the day''s cash and get it verified.', N'OPD.DAYCLOSING,OPD.DAYCLOSINGVERIFY', N'day closing cash collection verify cashier end of day', N'{"steps": ["OPD > OPD Day Closing: check the day''s collection by payment mode against the cash in hand and submit.", "A supervisor verifies it in OPD > OPD Day Closing Verification.", "Use Reports > OPD > OPD Cashier Day-end Closing for the detail."], "prereq": [], "tips": [], "next": []}', 220);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('OPD.CANCEL', 'GUIDE', 'OPD', N'Cancel an OPD bill or refund', N'Cancel a bill fully or partly and refund the patient.', N'OPD.BILLCANCELLATION.OPD', N'cancel bill refund opd cancellation', N'{"steps": ["OPD > Bill Cancellation & Refund: find the bill.", "Choose full or partial cancellation, the reason and the refund mode; it may need approval.", "Save; the cancellation note can be printed. It shows in the cancellation reports."], "prereq": [], "tips": [], "next": []}', 230);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('OPD.DUE', 'GUIDE', 'OPD', N'Collect a due payment on an OPD bill', N'Take the balance of an OPD bill that was saved unpaid or part-paid.', N'OPD.DASHBOARD', N'opd due payment collect due balance pending unpaid consultation bill partial payment receipt', N'{"steps": ["OPD > OPD Dashboard: choose the date and click the Payment due filter.", "Click the action menu (three dots) of the bill and choose Collect payment.", "Enter the amount received and the payment mode, then save; print the receipt."], "prereq": ["OPD.SERVICEBOOKING"], "tips": [], "next": []}', 240);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('OPD.COMMISSION', 'GUIDE', 'OPD', N'Doctor commission and disbursal', N'Pay doctors their share of OPD earnings.', N'OPD.DOCTORDISBURSAL,MASTER.DOCTORCOMMISSIONCONFIGS', N'doctor commission share payout disbursal tds settlement', N'{"steps": ["Set up the doctor''s share in Master > OPD Master > Doctor Commission Config.", "OPD > Doctor Commission & Disbursals: choose the doctor and period, review the earned amount, and record the payout.", "See Reports > Finance / Doctor Settlement and Reports > OPD (Doctor Share, Payout, TDS) for the statements."], "prereq": [], "tips": [], "next": []}', 250);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('LAB.B2C', 'GUIDE', 'LAB', N'Book tests for a walk-in patient (B2C billing)', N'Find or register the patient, add tests, take payment and print the bill.', N'LAB.LABORDERBOOKING.B2CBOOKING,LAB.LABORDERBOOKING.B2CORDERLIST', N'b2c booking lab billing bill tests walk in patient package discount payment print smart id scan', N'{"steps": ["LAB > LAB Order Booking > B2C Booking / Registration: search the patient by phone or ID - or register a new one on the same page (Smart ID Scan can read an Aadhaar / PAN / passport photo when AI is on).", "Choose the referring doctor and collection type (walk-in or home collection).", "Add tests, profiles or packages by name or code. AI suggestions may offer a cheaper package or often-ordered tests.", "Add misc charges if any (home collection...), apply a discount (may need approval) or redeem membership points.", "Collect payment and save. Print the bill (A4 or A5 as set in Hospital Settings); the patient can get it by email / WhatsApp."], "prereq": ["MASTER.LABINVESTIGATIONS", "MASTER.LABRATELISTB2C"], "tips": ["Uploading an Aadhaar / passport lets the system check the name, age and gender on save.", "B2C Order List shows the bills to reprint or open; a balance is collected there too (see ''Collect a due'')."], "next": ["LAB.SAMPLECOLLECTION"]}', 260);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('LAB.B2B', 'GUIDE', 'LAB', N'Book tests for a franchise or corporate (B2B)', N'Bill tests on the partner''s rates and account.', N'LAB.LABORDERBOOKING.B2BBOOKING,LAB.LABORDERBOOKING.B2BREGISTRATION,LAB.LABORDERBOOKING.B2BINVOICES,LAB.LABORDERBOOKING.B2BSETTLEMENT', N'b2b franchise corporate partner billing invoice settlement wallet credit', N'{"steps": ["LAB > LAB Order Booking > B2B Lab Billing & Booking: choose the partner (franchise / collection centre or corporate).", "Find or add the patient, add tests - prices come from the partner''s rate list.", "Save. The amount goes to the partner''s account (franchise wallet or credit).", "B2B Order List, B2B Invoices and B2B Multi-Bill Settlement handle invoicing and payments."], "prereq": ["MASTER.LABFRANCHISES", "MASTER.LABRATELISTFRANCHISE", "MASTER.CORPORATES"], "tips": ["A franchise needs balance in its wallet - top up in Utility > Franchise Top-Up."], "next": ["LAB.SAMPLECOLLECTION"]}', 270);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('LAB.COLLECT', 'GUIDE', 'LAB', N'Collect samples and print barcodes', N'Mark samples collected so they reach the lab for reporting.', N'LAB.SAMPLECOLLECTION', N'sample collection collect barcode label tube reject recollect phlebotomy', N'{"steps": ["LAB > Sample Collection Management: find the bill (today''s pending list or search).", "For each container print the barcode label and stick it on the tube.", "Click Collect (one sample, a profile, or all) - the collection time is recorded.", "If a sample is unsuitable choose Reject / Re-collect with a reason.", "Collected samples now appear in Lab Reporting Entry (or go to Sample Transfer if another branch tests them)."], "prereq": ["LAB.LABORDERBOOKING.B2CBOOKING"], "tips": [], "next": ["LAB.LABREPORTING", "LAB.SAMPLETRANSFER"]}', 280);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('LAB.TRANSFER', 'GUIDE', 'LAB', N'Send samples to another branch', N'Transfer samples to the branch that runs the test, and receive them there.', N'LAB.SAMPLETRANSFER', N'sample transfer send receive branch outsource', N'{"steps": ["LAB > Sample Transfer: choose the collected samples and the target branch, then Transfer.", "At the target branch open Sample Transfer, find the incoming samples and Receive them.", "Received samples appear in the target branch''s Lab Reporting."], "prereq": ["LAB.SAMPLECOLLECTION"], "tips": [], "next": ["LAB.LABREPORTING"]}', 290);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('LAB.REPORT', 'GUIDE', 'LAB', N'Enter, validate and approve results', N'Report the tests of a bill from entry to final approval.', N'LAB.LABREPORTING,LAB.LABIMAGEREPORTING,LAB.MICROBIOLOGYREPORTING', N'report entry result validate approve submit lab reporting critical flag delta previous trend image microbiology', N'{"steps": ["LAB > Lab Reporting Entry: filter by date (Sample Collection DateTime by default), department or search, then click Report Entry on the bill.", "Type the results. The flag (H / L / Critical) shows at once; ''Previous'' shows the last result and the graph icon opens the last 5 results with a trend.", "Add remarks if needed and click Submit.", "A senior validates (Validate) and the pathologist approves (Approve) - or approves from the Report Approval Dashboard when pathologist approval is required.", "A Critical / Panic result needs the communication recorded (who was informed) before sign-off.", "Approved reports can be printed and are emailed / sent by WhatsApp if switched on."], "prereq": ["LAB.SAMPLECOLLECTION", "SETTINGS.USERS", "MASTER.LABREFERENCERANGES"], "tips": ["The i icon on a bill opens its Audit History with the workflow from booking to delivery.", "Only users marked Lab Technician or Pathologist (or Administrators) can open reporting."], "next": ["LAB.PATHOLOGISTDASHBOARD", "LAB.LABREPORTDISPATCH"]}', 300);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('LAB.APPROVE', 'GUIDE', 'LAB', N'Approve reports as a pathologist', N'Sign off reports from the Report Approval Dashboard.', N'LAB.PATHOLOGISTDASHBOARD', N'pathologist approve sign off dashboard level authorize', N'{"steps": ["LAB > Report Approval Dashboard lists reports waiting for your level.", "Open a report, check the results, flags, previous values and remarks.", "Approve (or send back). With several levels, the report goes to the next level until the last one signs.", "Record critical value communication if asked."], "prereq": ["SETTINGS.LABAPPROVALFLOWS"], "tips": [], "next": ["LAB.LABREPORTDISPATCH"]}', 310);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('LAB.UNAPPROVE', 'GUIDE', 'LAB', N'Correct an approved report (Re-Test / Re-Collect)', N'Withdraw approval to correct a result or to draw a new sample.', N'LAB.LABUNAPPROVE', N'unapprove unauthorize re-test retest re-collect recollect correct amend revised report', N'{"steps": ["LAB > Un-Authorize Report: find the bill and choose the tests.", "Choose Re-Test (results go back for correction) or Re-Collect (a new sample is needed), and enter the reason.", "Correct and approve again (Re-Test) or collect the new sample and report it (Re-Collect).", "Send the revised report; the Audit History shows the rework."], "prereq": [], "tips": [], "next": ["LAB.LABREPORTING", "LAB.LABREPORTDISPATCH"]}', 320);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('LAB.DISPATCH', 'GUIDE', 'LAB', N'Deliver reports (print, email, WhatsApp)', N'Hand over or send approved reports.', N'LAB.LABREPORTDISPATCH', N'dispatch deliver print report email whatsapp send', N'{"steps": ["LAB > Lab Report Dispatch: search the bill / patient.", "Print the report, or send it by email / WhatsApp (needs the patient''s email / phone and the branch settings).", "The dispatch is recorded; a revised report is marked as revised."], "prereq": ["LAB.LABREPORTING"], "tips": [], "next": []}', 330);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('LAB.CANCEL', 'GUIDE', 'LAB', N'Cancel a LAB bill or refund', N'Cancel all or some tests and refund.', N'LAB.BILLCANCELLATION.LAB', N'cancel lab bill refund partial cancellation', N'{"steps": ["LAB > Bill Cancellation & Refund: find the bill.", "Choose full or partial cancellation, the tests, the reason and the refund mode; it may need approval.", "Save. Cancelled tests leave the work lists."], "prereq": [], "tips": [], "next": []}', 340);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('LAB.DUE', 'GUIDE', 'LAB', N'Collect a due (balance) payment on an existing LAB bill', N'Take the remaining amount of a B2C bill that was saved unpaid or part-paid, and give the money receipt.', N'LAB.LABORDERBOOKING.B2CORDERLIST', N'due payment collect due take due receive balance pending amount outstanding unpaid part paid partial payment existing bill old bill money receipt settle bill pay balance lab bill', N'{"steps": ["LAB > LAB Order Booking / Registration > B2C Order List.", "Find the bill: search by bill no, token, patient name or phone, and set Payment Status to Full Due or Partial Due (the due amount shows in red under the bill amount). Widen the dates for an older bill.", "Click the action menu (three dots) of the bill and choose Collect Payment - or open the bill and click Collect Payment at the bottom.", "The payment screen shows the bill amount, what was paid and the balance due. Enter the amount received (all or part of the due) with the payment mode (cash, card, UPI...).", "Save. A money receipt (A5) is offered for printing; the bill''s balance and payment status update at once."], "prereq": ["LAB.LABORDERBOOKING.B2CBOOKING"], "tips": ["The collected amount counts in the day''s collection of the person who takes it (Day Closing, Collection Register).", "Reports > LAB > Outstanding Dues lists every bill with a balance.", "A discount at due collection is possible only when the bill has no discount yet (one discount per bill); above the limit it needs approval."], "next": ["LAB.LABREPORTDISPATCH", "LAB.DAYCLOSING"]}', 350);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('LAB.B2BPAY', 'GUIDE', 'LAB', N'Collect payment on B2B bills (franchise / corporate)', N'Take a partner''s payment on one B2B bill or settle many bills at once.', N'LAB.LABORDERBOOKING.B2BREGISTRATION,LAB.LABORDERBOOKING.B2BSETTLEMENT,LAB.LABORDERBOOKING.B2BINVOICES', N'b2b payment partner payment franchise corporate due collect settle settlement multi bill outstanding credit', N'{"steps": ["One bill: LAB > LAB Order Booking / Registration > B2B Order List - find the bill and use Collect payment.", "Many bills: B2B Multi-Bill Settlement - choose the partner, tick the bills (or the period), enter the amount and payment mode and Settle.", "Print the settlement / receipt. Invoices for the period are in B2B Invoices."], "prereq": ["LAB.LABORDERBOOKING.B2BBOOKING"], "tips": [], "next": []}', 360);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('LAB.REPRINT', 'GUIDE', 'LAB', N'Reprint a LAB bill, money receipt or report', N'Print a bill or an approved report again.', N'LAB.LABORDERBOOKING.B2CORDERLIST,LAB.LABREPORTDISPATCH', N'reprint print again duplicate bill copy report print receipt print bill again', N'{"steps": ["LAB > LAB Order Booking / Registration > B2C Order List (B2B Order List for partners): find the bill.", "Action menu (three dots) > Print Bill - or Print Lab Report when tests are approved.", "Reports can also be printed or sent again from LAB > Lab Report Dispatch."], "prereq": [], "tips": [], "next": []}', 370);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('LAB.CLOSE', 'GUIDE', 'LAB', N'LAB day closing', N'Close the day''s LAB collection and get it verified.', N'LAB.DAYCLOSING,LAB.DAYCLOSINGVERIFY', N'lab day closing cash verify cashier', N'{"steps": ["LAB > LAB Day Closing: compare the day''s collection by payment mode with the cash and submit.", "A supervisor verifies it in LAB Day Closing Verification.", "Reports > LAB > Cashier Day-end Closing gives the detail."], "prereq": [], "tips": [], "next": []}', 380);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('LAB.AI', 'GUIDE', 'LAB', N'AI features at billing and reporting', N'Smart ID Scan, document check, test suggestions and reflex suggestions.', N'SETTINGS.HOSPITALSETTINGS', N'ai artificial intelligence smart id scan aadhaar pan ocr suggestion package reflex', N'{"steps": ["Switch on in Settings > Hospital Settings > Enable AI Features at Billing (per branch).", "Smart ID Scan: upload a photo / PDF of Aadhaar, PAN or passport in B2C / B2B booking; name, age, gender and address are filled in.", "Document check: on save, the details are compared with the uploaded Aadhaar / passport and differences are shown to confirm.", "Test suggestions: while adding tests, cheaper packages and tests often ordered together are suggested.", "Reflex suggestions: in Lab Reporting, follow-up tests suggested by Reflex Rules."], "prereq": [], "tips": [], "next": []}', 390);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('QC.IQC', 'GUIDE', 'QUALITY', N'Daily internal QC (IQC) and Levey-Jennings charts', N'Run QC, enter results and watch the charts.', N'QC.IQC.SETUP,QC.IQC.ENTRY,QC.IQC.CHART', N'iqc quality control westgard levey jennings lj chart lot target mean sd', N'{"steps": ["Quality & Compliance > Internal QC > QC Materials, Lots & Targets: set the control material, lot, level, mean and SD for each test / analyzer.", "Daily QC Entry: enter the QC results of the run; Westgard rule violations are flagged.", "Levey-Jennings Charts: see the trend and act on shifts or outliers (record a CAPA if needed)."], "prereq": ["QC.EQUIPMENT"], "tips": [], "next": ["QC.CAPA"]}', 400);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('QC.EQAS', 'GUIDE', 'QUALITY', N'EQAS, equipment and CAPA', N'External quality schemes, the equipment register and corrective actions.', N'QC.EQUIPMENT,QC.EQAS,QC.CAPA', N'eqas external quality equipment calibration maintenance capa corrective preventive', N'{"steps": ["Equipment Register: add each analyzer / instrument with calibration and maintenance schedules.", "EQAS Programmes & Results: record the scheme, the samples and your results against the peer group.", "CAPA Register: record a problem, its root cause, the corrective and preventive action and close it."], "prereq": [], "tips": [], "next": []}', 410);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('QC.BOM', 'GUIDE', 'QUALITY', N'Bill of material and test cost', N'Know what each test consumes and costs.', N'QC.BOM.TEST,QC.BOM.SAMPLEKIT,QC.BOM.COSTPREVIEW', N'bom bill of material cost reagent consumable margin kit', N'{"steps": ["Quality & Compliance > Masters: add items, suppliers and stores.", "Bill of Material > Test BOM: list the items (reagents, consumables) each test uses and the quantity.", "Sample Collection Kit: the kit used per sample.", "BOM Cost Preview and Reports > LAB (Test Cost Sheet, Price vs Cost, Margin Alert) show cost and margin."], "prereq": ["QC.MASTER.ITEMS"], "tips": [], "next": []}', 420);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('REP.USE', 'GUIDE', 'REPORTS', N'Use any report: filters, export and print', N'All reports work the same way.', N'', N'report filter export excel pdf print date range summary detail mis', N'{"steps": ["Open the report from the Reports menu (LAB, OPD, Finance / Doctor Settlement, Accounts).", "Choose the period (Today, 7 Days, This Month, Last Month or your dates) and the filters; click Apply / Show Report.", "Switch between Summary and Detail tabs; click a row or chart to drill down.", "Export with Excel or PDF; Print where offered."], "prereq": [], "tips": [], "next": []}', 430);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('REP.WORKLOAD', 'GUIDE', 'REPORTS', N'Testwise Workload report', N'Per test: patients, bills, status of samples and reports, turnaround and abnormal results.', N'REPORTS.LABTESTWISEWORKLOAD', N'workload testwise test wise patient count tat volume', N'{"steps": ["Reports > LAB > Testwise Workload: choose the bill dates; Head Office can choose a branch.", "Filter by department, test category / sub category, tests (profiles count as one test) and B2C / B2B.", "Tabs: Workload Summary, Test-wise Patient Count and Patient-wise Details (click a test to drill down).", "Export Excel (all three) or PDF (the tab you are on)."], "prereq": [], "tips": [], "next": []}', 440);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('REP.DAILY', 'GUIDE', 'REPORTS', N'Daily billing, collection and dues', N'Check what was billed, what was collected and what is still due.', N'REPORTS.LABBILLINGREGISTER,REPORTS.LABB2CCOLLECTIONREGISTER,REPORTS.LABOUTSTANDINGDUES,REPORTS.LABDISCOUNTREGISTER,REPORTS.OPDBILLINGREGISTER,REPORTS.DAILYCOLLECTION,REPORTS.OPDOUTSTANDINGDUES', N'billing register collection dues outstanding ageing discount cancellation refund daily', N'{"steps": ["Reports > LAB > Daily Billing Register (or OPD Daily Billing Register): every bill of the period.", "Daily Collection Register: money collected by mode and cashier.", "Outstanding Dues & Ageing: unpaid balances by age.", "Discount Register and Cancellation & Refund Register: discounts given (with reason and approver) and cancellations."], "prereq": [], "tips": [], "next": []}', 450);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('UT.TEMPLATES', 'GUIDE', 'UTILITY', N'Change the wording of system emails (Email Templates)', N'Edit the booking and prescription emails in a designer - no HTML needed.', N'UTILITY.EMAILTEMPLATE', N'email template wording booking confirmation prescription designer preview', N'{"steps": ["Utility > Email Templates: click Edit / Preview on an email.", "Change the subject, heading, message (purple chips are patient details filled in automatically), the details box, note and closing.", "The preview on the right shows the email exactly as the patient gets it; Send test emails it to you.", "Save. A missing template means that email is not sent - add it from the list page."], "prereq": ["SETTINGS.SMTPCONFIG"], "tips": [], "next": []}', 460);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('UT.CAMPAIGN', 'GUIDE', 'UTILITY', N'Send an email to all (or chosen) patients, users or doctors - Campaigns', N'Email many people (or a few chosen ones) at once.', N'UTILITY.CAMPAIGNS', N'campaign bulk send email patients everyone mass mailing newsletter health camp promotion staff schedule', N'{"steps": ["Utility > Campaigns > New Campaign.", "1 Campaign: name it and choose Send from (the branch whose mail account sends it).", "2 Recipients: Patients, Users or Doctors; then Everyone, A filtered group (branch, gender, age, visit dates, role, speciality) or Choose people. The box shows how many will get it.", "3 Message: start from a template or write it; Insert field adds the person''s name etc. Check the preview and Send test to yourself.", "4 Send now or Schedule for a time. Watch the results page: sent, waiting, failed (with reason) and skipped; cancel or retry failed."], "prereq": ["SETTINGS.SMTPCONFIG"], "tips": ["Patients can unsubscribe with the link in the email; they are skipped from then on.", "Save messages you send often as Templates (Templates tab)."], "next": []}', 470);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('UT.AUDIT', 'GUIDE', 'UTILITY', N'Audit log and email log', N'See who did what, and whether emails went out.', N'UTILITY.AUDITLOGS,UTILITY.EMAILLOGS', N'audit log history who changed email log failed sent', N'{"steps": ["Utility > Audit Log: filter by date, user, module or text to see actions (sign-in, billing, approvals, changes).", "Utility > Email Logs: every email sent or failed, with the reason for failures.", "On a LAB bill, the i icon shows its own audit history and workflow."], "prereq": [], "tips": [], "next": []}', 480);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('UT.FRANCHISE', 'GUIDE', 'UTILITY', N'Franchise wallet top-up and dashboard', N'Add money to a franchise''s wallet and watch its business.', N'UTILITY.FRANCHISETOPUP,UTILITY.FRANCHISEDASHBOARD', N'franchise wallet top up recharge balance dashboard', N'{"steps": ["Utility > Franchise Top-Up: choose the franchise, enter the amount and payment details, save (may need approval).", "Utility > Franchise Dashboard: bookings, wallet balance and dues of each franchise.", "Reports > LAB > Franchise Wallet Statement: every credit and debit."], "prereq": ["MASTER.LABFRANCHISES"], "tips": [], "next": []}', 490);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('UT.PORTAL', 'GUIDE', 'UTILITY', N'Patient portal login', N'Give a patient access to the patient portal.', N'UTILITY.PATIENTPORTAL.LOGIN', N'patient portal login credentials app', N'{"steps": ["Utility > Patient Login: find the patient (must have an email).", "Generate the login; the patient gets the user name and password by email.", "The patient signs in to see bookings and reports and should change the password."], "prereq": [], "tips": [], "next": []}', 500);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('UT.PETTY', 'GUIDE', 'UTILITY', N'Petty cash and vouchers', N'Record small expenses and close petty cash.', N'UTILITY.ACCOUNTS.PETTYEXPENSE,UTILITY.ACCOUNTS.COUNTERS,UTILITY.ACCOUNTS.CLOSING,UTILITY.ACCOUNTS.VOUCHERS,UTILITY.ACCOUNTS.LEDGERS,UTILITY.ACCOUNTS.EXPENSEHEADS,UTILITY.ACCOUNTS.PAYEES,UTILITY.ACCOUNTS.SETTINGS', N'petty cash expense voucher ledger accounts payee closing', N'{"steps": ["Utility > Accounts > Accounts Settings, Expense Heads, Payees and Ledgers: set up once.", "Petty Cash Counters: the counters that hold cash.", "Petty Expenses: record each expense with head, payee, amount and bill.", "Petty Cash Closing: close the counter''s day; Voucher Entry for accounting vouchers."], "prereq": ["UTILITY.ACCOUNTS.SETTINGS"], "tips": [], "next": []}', 510);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('UT.PRINTTEMPLATES', 'GUIDE', 'UTILITY', N'Design the bill and lab report header and footer (Print Templates)', N'Make your own letterhead for bills (LAB, OPD, receipts) and lab reports, and choose which branch prints with it.', N'UTILITY.PRINTTEMPLATES', N'print template header footer letterhead bill report logo layout design customise branch', N'{"steps": ["Utility > Print Templates > New Template: give it a name, choose Bills or Lab Reports, and start from Standard, Centred or Blank.", "In the designer, click any part of the header or footer on the page to select it; its settings open on the right.", "Add to a column with the buttons on the left: Data field (pick hospital name, address, phone, email, NABH, GST... from a list - nothing is typed), Logo, Text, Image / seal, Barcode, Line, Space, Page number.", "Add rows with Full, ½ ½, ⅓ ⅓ ⅓ or Logo · Name · Right; change a column''s width and move blocks up / down on the right.", "Or drag on the page: a block into another column or place, the edge between two columns for their width, the bottom edge of a logo / image / barcode / space for its height, the ⋮⋮ grip to move a row, the purple bar under the header or footer for its height.", "Fill with: choose a branch to see its own details on the page. Fields a branch has left empty are skipped when printing.", "Preview prints a real recent bill or lab report with your draft. Save draft keeps it private; Publish makes it the live version.", "Back on Print Templates, choose the template for each branch under \"Which branch prints with which template\". Classic = the built-in header and footer."], "prereq": [], "tips": ["Templates are created, published and assigned by the head office; other branches can open and preview them only.", "Role Permissions > Print Templates: View, Edit (design), Publish, Assign (branch templates) and Delete are separate controls.", "The bill / report body never changes - only the header and footer come from the template.", "Text style: choose the font (Arial, Calibri, Georgia, Times New Roman ...), size, colour, Bold / Italic / Underline / Strikethrough / CAPITALS and letter spacing; \"Use this font for every block\" sets one font for the whole header and footer.", "Printer cuts the top or bottom? Select the header (or footer) and set \"Space above (mm)\" / \"Space below (mm)\" - e.g. 5-8 mm above the header when an A5 print cuts the hospital name. The space is real paper size and is added to the page margin, on bills and lab reports alike.", "\"Required B2C Bill / Lab Report Print Header = No\" (pre-printed paper) still leaves the space blank; emailed and WhatsApp copies always carry the template.", "Every publish is kept as a version: Restore brings an older one back into the draft.", "Undo with the arrow button or Ctrl+Z."], "next": []}', 520);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('ACC.SETUP', 'GUIDE', 'UTILITY', N'Set up Accounts: bank ledgers and payment mode ledgers', N'Decide which cash or bank ledger each payment method (Cash, Card, UPI, NEFT, Cheque, Wallet) posts to - once, from the head office.', N'UTILITY.ACCOUNTS.SETTINGS,UTILITY.ACCOUNTS.LEDGERS', N'payment mode ledger bank account cash upi card neft cheque mapping bank book cash book contra deposit clearing', N'{"steps": ["Utility > Accounts > Ledgers and Groups: create one ledger for each real bank account (e.g. \"HDFC Current A/c\") under the group Bank Accounts. For card / UPI money that reaches the bank a day later you may also create a clearing ledger (e.g. \"Card / UPI Clearing\") under Bank Accounts.", "Utility > Accounts > Accounts Settings > Payment Mode Ledgers: for every payment method choose the ledger in the column All branches (Cash -> Cash Account, Card / UPI -> your bank or clearing ledger, NEFT / Cheque -> your bank).", "If a branch banks elsewhere, choose its own ledger in that branch''s column; leave \"Same as all branches\" otherwise.", "Click Save Payment Mode Ledgers. Every new receipt, refund, B2B settlement, franchise wallet top-up and membership card payment posts to the chosen ledger.", "Check the next day in Reports > Accounts > Cash Book / Bank Book that the money is in the right book."], "prereq": ["UTILITY.ACCOUNTS.SETTINGS"], "tips": ["Only the head office can change the mapping; branches see it read-only.", "Entries already posted keep their ledger - the mapping applies from the next entry.", "Cash deposited into the bank: Voucher Entry > Contra (Dr the bank ledger, Cr Cash Account)."], "next": ["UTILITY.ACCOUNTS.OPENING"]}', 530);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('ACC.OPENING', 'GUIDE', 'UTILITY', N'Enter opening balances (go-live)', N'Bring the balances of the day the books start here - cash, bank, receivables, payables, capital - branch by branch.', N'UTILITY.ACCOUNTS.OPENING', N'opening balance go live start books brought forward capital difference first day financial year', N'{"steps": ["Utility > Accounts > Opening Balances. The head office chooses the branch; a branch user sees only its own.", "Set Opening as of: the first day of the financial year, or the go-live date.", "Enter each balance on its side: assets (cash, bank, receivables, advances) usually under Debit; liabilities and capital (payables, loans, capital) under Credit. Leave the rest blank.", "Watch Difference at the bottom: it should read Balanced. Then click Save Opening Balances.", "The balances are posted as one Opening Balance voucher (OPN/...); the Trial Balance, Ledger Statement, Cash Book and Bank Book start from them."], "prereq": ["UTILITY.ACCOUNTS.LEDGERS", "UTILITY.ACCOUNTS.SETTINGS"], "tips": ["Saving again replaces the branch''s opening entry: the old one is cancelled (kept for audit), never deleted.", "If debits and credits differ, the difference is held in \"Opening Balance Difference\" (Capital Account) and the screen warns you - correct it before closing the first month.", "Income and expense ledgers always start at zero - they are not on this screen.", "A branch whose books are locked on or after the opening date cannot take the entry: unlock it first in Accounts Settings."], "next": ["REPORTS.ACCOUNTS"]}', 540);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('ACC.RECON', 'GUIDE', 'REPORTS', N'Reconcile bills with the ledger (Bill Reconciliation)', N'Make sure what the books say patients owe is exactly what the bills say - and fix what was missed.', N'REPORTS.ACCOUNTS', N'reconciliation reconcile receivable ledger mismatch difference repair missing posting duplicate patient receivable books bills', N'{"steps": ["Reports > Accounts > Bill Reconciliation. The head office can pick a branch or see all.", "Look at the Patient Receivable card: \"agrees\" means the books and the bills match. \"differs by\" shows the gap.", "Can be repaired lists bills whose entries are missing or wrong - a bill, receipt, refund or cancellation that was not posted, a B2B bill posted twice, or an entry left behind by a deleted bill.", "Click Repair. Missing entries are posted on their own date; wrong ones are reversed by a new entry. Nothing is edited or deleted, and running it again changes nothing.", "Needs a person to check lists bills the repair does not touch: a bill without a payment record (collect it or cancel the bill) and a bill whose payment rows do not add up to its Total Paid (stray or test rows - check the bill).", "Open any bill from the list (the bill number opens its print) to check it."], "prereq": [], "tips": ["Run it at least once a month, before locking the books.", "Patient credit: money kept after a cancellation or an over-payment is shown as a credit the patient is owed - refund it from the bill.", "Repair needs the Repair permission on Reports > Accounts (Settings > Security > Role Permissions)."], "next": ["REPORTS.ACCOUNTS"]}', 550);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('ACC.MONTHEND', 'GUIDE', 'REPORTS', N'Month-end: check and close the books', N'The checks to run before a month is final, then lock it.', N'REPORTS.ACCOUNTS,UTILITY.ACCOUNTS.SETTINGS', N'month end closing lock books trial balance cash book bank book reconcile audit period close', N'{"steps": ["Reports > Accounts > Bill Reconciliation: Patient Receivable agrees with the bills (Repair what can be repaired).", "Reports > Accounts > Ledger Posting Audit for the month: no document left unposted.", "Reports > Accounts > Cash Book and Bank Book: closing balances match the counted cash and the bank statement.", "Reports > Accounts > Trial Balance: debits equal credits and no unbalanced voucher is reported.", "Utility > Accounts > Accounts Settings > Books Lock: lock each branch up to the last day of the month."], "prereq": ["UTILITY.ACCOUNTS.OPENING"], "tips": ["A locked branch takes no voucher, petty expense or closing dated on or before the lock date; billing is never stopped.", "Voucher numbers restart every financial year: RCT/HO/26-27/00001, then RCT/HO/27-28/00001."], "next": []}', 560);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('SET.LOGINRETRY', 'GUIDE', 'SETTINGS', N'Lock accounts after wrong passwords and unlock a user', N'Set how many wrong passwords are allowed before an account is locked for 10 minutes, and unlock a user early.', N'SETTINGS.HOSPITALSETTINGS,SETTINGS.USERS', N'login retry wrong password attempts lock lockout unlock locked user security brute force', N'{"steps": ["Settings > Hospital Settings > OPD Configuration > Login Retry Count: 0 (default) means no lock; any number from 1 to 20 is the wrong passwords allowed.", "After each wrong password the user sees how many attempts are left. When they run out, the account is locked for 10 minutes.", "To unlock early: Settings > User Master, filter Status = Locked (the count is shown in the filter). A locked user has a \"Locked till\" badge.", "Click the unlock button on the user''s row, confirm the user''s identity, enter the reason and click Unlock. The user can sign in at once; the reason is kept in the audit log."], "prereq": [], "tips": ["A user in several branches gets the strictest count of those branches; a user without a branch (Super Admin) gets the head office''s.", "Unlock needs its own permission (User Master > Unlock) - give it only to administrators.", "Unlock does not change an Inactive user - activate the user in User Master for that."], "next": []}', 570);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('AI.DATA', 'GUIDE', 'GENERAL', N'Ask eMedi: find a bill, open screens and see today''s numbers', N'Ask eMedi also answers from live data - only what your role may see, only in your branch.', N'HOME.DASHBOARD', N'ask emedi ask ai data bill number open bill report entry sample collection barcode collection revenue dues today token patient search', N'{"steps": ["Type a bill number (LAB/HO2627000295 or just HO2627000295): the bill card shows the patient, amount, paid, due, samples and reports, with buttons for the bill''s screens.", "Add what you want to open: \"... open bill\", \"... lab reporting entry\", \"... print report\", \"... sample collection\", \"... barcode\". That screen opens at once (Report Entry opens the right one for the bill''s tests: Lab, Image or Microbiology).", "A token (\"token LAB-HO-0003\"), a phone number or a Patient ID finds the bill or patient.", "Numbers of a period: \"today''s collection\", \"opd revenue this month\", \"how many bills last month\", \"pending dues\", \"pending samples today\", \"reports pending approval\".", "How-to questions (\"how do I collect a due\") still get the help guides."], "prereq": [], "tips": ["Spelling mistakes are understood (\"colection yesturday\").", "Every night Ask eMedi learns the answers several users chose for the same question; administrators see it in Help Insights."], "next": []}', 580);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('FAQ.MENU.MISSING', 'FAQ', 'GENERAL', N'Why can''t I see a menu or page?', N'Menus show only the pages your role may open. Ask your administrator to give the page to your role in Settings > Security > Role Permissions (or to you in User Permissions). Lab Reporting also needs the Lab Technician or Pathologist tick in User Master.', N'SETTINGS.SECURITY.ROLEPERMISSIONS', N'menu missing page not visible access denied permission', N'{"steps": [], "prereq": [], "tips": [], "next": []}', 590);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('FAQ.SWITCH.BRANCH', 'FAQ', 'GENERAL', N'How do I work in another branch?', N'Open your profile menu (top right) and choose Switch Branch, pick the branch and continue. Bills and reports you make belong to the branch shown in the HO / branch badge.', N'', N'switch branch change branch another centre', N'{"steps": [], "prereq": [], "tips": [], "next": []}', 600);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('FAQ.SESSION', 'FAQ', 'GENERAL', N'Why was I signed out?', N'For safety you are signed out after a period without activity, or when the browser tab session ends. Sign in again; unsaved work on the page is lost, so save often.', N'', N'logout signed out session timeout idle', N'{"steps": [], "prereq": [], "tips": [], "next": []}', 610);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('FAQ.LOCKED', 'FAQ', 'GENERAL', N'My account is locked. What do I do?', N'When your branch has a Login Retry Count, that many wrong passwords lock the account for 10 minutes - the message shows when you can try again. Wait, reset the password with Forgot password?, or ask an administrator to unlock you in User Master (filter Status = Locked).', N'SETTINGS.USERS,SETTINGS.HOSPITALSETTINGS', N'locked account wrong password attempts lockout unlock retry', N'{"steps": [], "prereq": [], "tips": [], "next": []}', 620);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('FAQ.ACC.VOUCHERNO', 'FAQ', 'UTILITY', N'How are voucher numbers formed?', N'Type / branch / financial year / number - e.g. RCT/HO/26-27/00042 is the 42nd Receipt of Head Office in 2026-27. SLS = sales (bills), RCT = receipts and refunds, CN = discounts, cancellations and reversals, PMT / CTR / JRN = manual payment, contra and journal, PCV = petty cash, OPN = opening balances. Every entry has its own number; it restarts each financial year. Entries made before October 2026 were renumbered this way; their old number (VCH-...) is kept with them.', N'REPORTS.ACCOUNTS', N'voucher number numbering format prefix financial year rct sls cn vch', N'{"steps": [], "prereq": [], "tips": [], "next": []}', 630);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('FAQ.TOKEN.SEQ', 'FAQ', 'OPD', N'Why do OPD and LAB tokens have their own numbers?', N'Each kind of bill has its own daily token sequence per branch: OPD (HO-0001), B2C LAB (LAB-HO-0001) and B2B LAB (B2B-LAB-HO-0001). An OPD bill never uses up a LAB token number, so each sequence runs without gaps; all restart at 0001 every day.', N'OPD.SERVICEBOOKING,LAB.LABORDERBOOKING.B2CBOOKING', N'token number gap sequence opd lab b2b skip missing', N'{"steps": [], "prereq": [], "tips": [], "next": []}', 640);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('FAQ.ACC.RECEIVABLE', 'FAQ', 'UTILITY', N'Why does Patient Receivable not match the dues report?', N'The ledger counts every patient''s balance, including credits (money kept after a cancellation or over-payment), while the dues report shows only amounts owed. Reports > Accounts > Bill Reconciliation explains every difference bill by bill and repairs missing or duplicate entries.', N'REPORTS.ACCOUNTS', N'patient receivable mismatch dues ledger difference credit reconciliation', N'{"steps": [], "prereq": [], "tips": [], "next": []}', 650);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('FAQ.PASSWORD.RULES', 'FAQ', 'GENERAL', N'What are the password rules?', N'At least 8 characters with at least one letter and one number. Choose one you do not use elsewhere.', N'', N'password rules length strong', N'{"steps": [], "prereq": [], "tips": [], "next": []}', 660);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('FAQ.TONE', 'FAQ', 'GENERAL', N'How do I turn the notification sound on or off?', N'Click the bell, then the speaker button at the top of the panel. It is remembered for that browser. Browsers play sound only after you have clicked on the page once.', N'', N'notification sound tone mute bell', N'{"steps": [], "prereq": [], "tips": [], "next": []}', 670);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('FAQ.A5', 'FAQ', 'LAB', N'How do I print LAB bills on half a page (A5)?', N'Settings > Hospital Settings > LAB > Printing: set LAB Bill Print Page Size to A5 landscape. Bills of that branch then print on half an A4 sheet.', N'SETTINGS.HOSPITALSETTINGS', N'a5 half page bill print size landscape', N'{"steps": [], "prereq": [], "tips": [], "next": []}', 680);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('FAQ.DISCOUNT.APPROVAL', 'FAQ', 'LAB', N'Why does my discount need approval?', N'Discounts above the limit set in Settings > Approval Matrix need an approver. The approver gets a notification and approves in Utility > Approval Dashboard; then the bill can be completed. One discount is allowed per bill.', N'SETTINGS.APPROVALMATRIX,UTILITY.APPROVALDASHBOARD', N'discount approval limit approver', N'{"steps": [], "prereq": [], "tips": [], "next": []}', 690);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('FAQ.DUE.DISCOUNT', 'FAQ', 'LAB', N'Can I give a discount while collecting a due?', N'Yes, if the bill has no discount yet - a bill gets one discount only. Apply it on the payment screen when you collect the due; above your limit it needs approval. If the bill already has a discount, or a membership benefit was applied, the discount is locked.', N'LAB.LABORDERBOOKING.B2CORDERLIST,SETTINGS.APPROVALMATRIX', N'discount at due collection due discount second discount locked', N'{"steps": [], "prereq": [], "tips": [], "next": []}', 700);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('FAQ.DUE.LIST', 'FAQ', 'LAB', N'Where do I see all bills with a balance due?', N'In LAB > B2C Order List set Payment Status to Full Due or Partial Due; Reports > LAB > Outstanding Dues lists every bill with a balance for any period.', N'LAB.LABORDERBOOKING.B2CORDERLIST,REPORTS.LABOUTSTANDINGDUES', N'due list outstanding pending payment bills balance unpaid report', N'{"steps": [], "prereq": [], "tips": [], "next": []}', 710);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('FAQ.PACKAGE.SUGGEST', 'FAQ', 'LAB', N'Why did the system suggest a package?', N'With AI features on, test suggestions compare the tests you added with packages that contain them at a lower price. Click Switch to use the package; your tests are replaced by it.', N'', N'package suggestion cheaper ai switch', N'{"steps": [], "prereq": [], "tips": [], "next": []}', 720);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('FAQ.MEMBERSHIP.POINTS', 'FAQ', 'LAB', N'How do I redeem membership points at billing?', N'Choose the patient with an active card, click Redeem points, enter the points; an OTP goes to the card holder''s phone / email. Enter it to apply the value to the bill.', N'', N'membership points redeem otp card', N'{"steps": [], "prereq": [], "tips": [], "next": []}', 730);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('FAQ.REPORT.EMAIL', 'FAQ', 'LAB', N'How do reports reach patients by email or WhatsApp?', N'Switch on report email / WhatsApp in Hospital Settings (LAB) and set up Email / WhatsApp Configuration for the branch. When a bill''s reports are approved they are sent automatically; you can also send from Lab Report Dispatch.', N'LAB.LABREPORTDISPATCH,SETTINGS.HOSPITALSETTINGS', N'report email whatsapp send patient automatic', N'{"steps": [], "prereq": [], "tips": [], "next": []}', 740);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('FAQ.PROFILE.COUNT', 'FAQ', 'REPORTS', N'In Testwise Workload, why is a profile counted as one test?', N'A profile booked on a bill is one test of the Investigation Master (for example Lipid Profile Total). Its status shows the stage all its tests reached. A package counts as the profiles and tests in it.', N'REPORTS.LABTESTWISEWORKLOAD', N'profile count one test workload', N'{"steps": [], "prereq": [], "tips": [], "next": []}', 750);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('FAQ.CRITICAL', 'FAQ', 'LAB', N'What is critical value communication?', N'A Critical or Panic result must be told to the doctor / patient quickly. Before the report is signed, record who was informed, how and when (Record critical value communication). The Critical & Panic Value Register lists them.', N'LAB.LABREPORTING,REPORTS.LABCRITICAL', N'critical panic value communication inform doctor', N'{"steps": [], "prereq": [], "tips": [], "next": []}', 760);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('FAQ.DELTA', 'FAQ', 'LAB', N'What does ''Previous'' and the graph icon show in result entry?', N'Previous is the patient''s last result of the same test (delta check). The graph icon opens the last 5 results with dates and a trend graph, with the normal range shaded.', N'LAB.LABREPORTING', N'previous delta check trend graph history last results', N'{"steps": [], "prereq": [], "tips": [], "next": []}', 770);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('FAQ.WORKFLOW', 'FAQ', 'LAB', N'How can I see where a LAB bill stands?', N'Click the i icon on the bill in Lab Reporting (and other LAB lists). Audit History shows the workflow from booking to delivery - each stage done, in progress or pending, with rework such as Re-Test or Re-Collect - and every recorded activity.', N'LAB.LABREPORTING', N'status workflow audit history track bill stage', N'{"steps": [], "prereq": [], "tips": [], "next": []}', 780);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('FAQ.CAMPAIGN.SKIP', 'FAQ', 'UTILITY', N'Why were some campaign recipients skipped?', N'People without an email address, patients who unsubscribed, and people sharing an email with another recipient (sent once) are skipped. The results page shows the reason for each.', N'UTILITY.CAMPAIGNS', N'campaign skipped not sent unsubscribed no email', N'{"steps": [], "prereq": [], "tips": [], "next": []}', 790);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('FAQ.TEMPLATE.FIELDS', 'FAQ', 'UTILITY', N'What are the purple chips in the email designer?', N'They are fields - the patient''s name, the doctor, the date, the hospital name and so on. They are filled in for each person when the email is sent. Insert them with Insert field.', N'UTILITY.EMAILTEMPLATE,UTILITY.CAMPAIGNS', N'field chip placeholder merge name email designer', N'{"steps": [], "prereq": [], "tips": [], "next": []}', 800);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('FAQ.EXPORT', 'FAQ', 'REPORTS', N'Can I export reports to Excel or PDF?', N'Yes - use the Excel and PDF buttons on the report. Some reports build the files on the server with all rows even when the screen shows only the first part.', N'', N'export excel pdf download report', N'{"steps": [], "prereq": [], "tips": [], "next": []}', 810);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('FAQ.HO.BRANCH', 'FAQ', 'REPORTS', N'Why do I only see my branch in reports?', N'Reports show the branch you are working in. Head Office users can choose another branch or all branches where the report offers it.', N'', N'report branch all branches head office', N'{"steps": [], "prereq": [], "tips": [], "next": []}', 820);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('FAQ.DUPLICATE.PATIENT', 'FAQ', 'OPD', N'How do I avoid duplicate patients?', N'Always search by phone (and name) before registering. Family members may share a phone - pick the right person from the list. Membership card issue fills in an existing patient when you choose the phone.', N'', N'duplicate patient search phone family', N'{"steps": [], "prereq": [], "tips": [], "next": []}', 830);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('FAQ.OPD.EMAIL', 'FAQ', 'OPD', N'Why did the patient not get the booking or prescription email?', N'The patient needs an email address, the branch needs Email Configuration, and the template (Booking Confirmation / Prescription Delivery) must exist and be active for the branch in Utility > Email Templates. Check Utility > Email Logs for the reason.', N'UTILITY.EMAILTEMPLATE,UTILITY.EMAILLOGS', N'booking email prescription email not received opd', N'{"steps": [], "prereq": [], "tips": [], "next": []}', 840);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('FAQ.APPROVAL.WHERE', 'FAQ', 'UTILITY', N'Where do I approve requests?', N'Utility > Approval Dashboard lists requests waiting for you (discounts, master changes, top-ups...). The bell also notifies you; click the notification to open it.', N'UTILITY.APPROVALDASHBOARD', N'approve request pending approval dashboard', N'{"steps": [], "prereq": [], "tips": [], "next": []}', 850);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('FAQ.IQC.WESTGARD', 'FAQ', 'QUALITY', N'What do the Westgard flags in Daily QC mean?', N'They are rules that detect errors in QC results (for example 1-3s: one value beyond 3 SD; 2-2s: two in a row beyond 2 SD). A rejection rule means: do not report patient results of that run until the cause is fixed; record a CAPA.', N'QC.IQC.ENTRY', N'westgard rule 1-3s 2-2s qc reject warning', N'{"steps": [], "prereq": [], "tips": [], "next": []}', 860);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('FAQ.HELP.ASK', 'FAQ', 'GENERAL', N'How do I ask the Help Assistant?', N'Click Ask eMedi at the bottom right of Home, or open Utility > Help Center, and type your question in plain words - for example ''how do I cancel a bill'' or ''after creating a B2C bill, what is next?''. It answers with steps, the screens to open and where the step sits in the workflow; tell it whether the answer helped.', N'', N'help assistant ask question ai', N'{"steps": [], "prereq": [], "tips": [], "next": []}', 870);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('TS.SAMPLE.NOT.IN.REPORTING', 'TROUBLE', 'LAB', N'A sample does not appear in Lab Reporting Entry', N'Reporting lists only collected, in-house samples of the dates and departments you can see.', N'LAB.LABREPORTING,LAB.SAMPLECOLLECTION', N'sample missing not showing lab reporting not visible', N'{"steps": ["Check the sample is Collected in Sample Collection (pending or rejected samples are not listed).", "The date filter is Sample Collection DateTime by default - widen the dates or switch Filter by date to Booking Date.", "Check the department / category filters and your Department Access in User Master.", "If the sample was transferred, it shows at the receiving branch after Receive.", "Outsourced tests are not reported here."], "prereq": [], "tips": [], "next": []}', 880);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('TS.REPORTING.DENIED', 'TROUBLE', 'LAB', N'Lab Reporting says access is denied', N'Lab Reporting is open only to users marked Lab Technician or Pathologist (or Administrators), in addition to page permission.', N'SETTINGS.USERS,LAB.LABREPORTING', N'access denied lab reporting technician pathologist', N'{"steps": ["Ask the administrator to tick Lab Technician or Pathologist for you in Settings > User Master.", "Check your role has the Lab Reporting page in Role Permissions.", "Sign out and in again after the change."], "prereq": [], "tips": [], "next": []}', 890);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('TS.CANNOT.APPROVE', 'TROUBLE', 'LAB', N'I cannot approve a report', N'Approval may be reserved to the Report Approval Dashboard, need your level in the approval flow, or wait for critical value communication.', N'LAB.PATHOLOGISTDASHBOARD,SETTINGS.LABAPPROVALFLOWS', N'cannot approve approve button missing sign off blocked', N'{"steps": ["If Hospital Settings says Pathologist approval required, approve from LAB > Report Approval Dashboard.", "Check you are a user of the right level in Settings > Pathologist Approval Flow.", "If a result is Critical / Panic, record the critical value communication first.", "Results must be submitted (and validated, if your flow uses validation) before approval.", "Your role needs the Approve action on the page."], "prereq": [], "tips": [], "next": []}', 900);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('TS.EMAIL.NOT.SENT', 'TROUBLE', 'SETTINGS', N'Emails are not being sent', N'Emails need the branch''s mail settings, a correct address and a working mail server.', N'SETTINGS.SMTPCONFIG,UTILITY.EMAILLOGS', N'email not sent failed smtp mail not received emails not going not delivered not working bounce', N'{"steps": ["Settings > Email Configuration: the branch has an Active, Default configuration; use Test Email.", "Utility > Email Logs shows each failure with the reason (wrong password, blocked, invalid address).", "With Gmail / Office 365 use an app password and the right port (587 STARTTLS or 465 SSL).", "The recipient must have a valid email; ask them to check Spam."], "prereq": [], "tips": [], "next": []}', 910);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('TS.RESET.NO.EMAIL', 'TROUBLE', 'GENERAL', N'The password reset email does not arrive', N'The link is sent only to the email on your user account, with the Head Office mail settings.', N'SETTINGS.USERS', N'reset email not received forgot password link password reset not working reset mail not coming', N'{"steps": ["Check Spam / Junk and wait a minute.", "Make sure your user account has your email (User Master) - ask the administrator.", "If several accounts share the email, enter your user name instead.", "At most 3 links are sent per 15 minutes; the newest link cancels older ones."], "prereq": [], "tips": [], "next": []}', 920);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('TS.SLOW', 'TROUBLE', 'GENERAL', N'The application is slow', N'Most slowness comes from the network between the application and the database server, or very large date ranges.', N'', N'slow loading performance hang lag', N'{"steps": ["Try a shorter date range or more filters on lists and reports.", "Check your internet connection; ask IT whether the database server is reachable without packet loss.", "Close unused tabs of the application; refresh the page.", "If one page is always slow, tell your administrator which page and what you did."], "prereq": [], "tips": [], "next": []}', 930);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('TS.PRINT.WRONG', 'TROUBLE', 'LAB', N'The bill prints on the wrong page size', N'The page size is set per branch in Hospital Settings and must match the printer paper.', N'SETTINGS.HOSPITALSETTINGS', N'print size wrong page a4 a5 printer bill', N'{"steps": ["Settings > Hospital Settings > LAB > Printing: choose A4 or A5 landscape.", "In the print dialog choose the same paper size, scale 100% and no headers / footers."], "prereq": [], "tips": [], "next": []}', 940);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('TS.ACC.BILL.MISSING', 'TROUBLE', 'UTILITY', N'A bill or receipt is missing from the Cash Book / ledger', N'The ledger entry is posted right after the bill or payment is saved; if that step failed (for example the connection dropped), the document is saved but its entry is not.', N'REPORTS.ACCOUNTS', N'missing ledger entry cash book bill not posted receipt not posted repair reconciliation', N'{"steps": ["Reports > Accounts > Bill Reconciliation (or Ledger Posting Audit for the period) lists it.", "Click Repair on Bill Reconciliation: the missing entry is posted on the document''s own date.", "If it stays under \"Needs a person to check\", open the bill - its payment rows do not agree with its Total Paid, or it has no payment record."], "prereq": [], "tips": [], "next": []}', 950);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('TS.ACC.WRONG.BOOK', 'TROUBLE', 'UTILITY', N'Card / UPI money shows in the wrong bank (or in cash)', N'Each payment method posts to the ledger chosen in Accounts Settings > Payment Mode Ledgers; it was set to another ledger when the payment was saved.', N'UTILITY.ACCOUNTS.SETTINGS,UTILITY.ACCOUNTS.VOUCHERS', N'wrong bank ledger upi card cash book bank book payment mode mapping', N'{"steps": ["Head office: Utility > Accounts > Accounts Settings > Payment Mode Ledgers - choose the right ledger for the method (and branch) and save; new payments follow it.", "Entries already posted: move them with a Contra voucher (Dr the right ledger, Cr the wrong one) in Voucher Entry."], "prereq": [], "tips": [], "next": []}', 960);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('TS.SAVE.ERROR', 'TROUBLE', 'GENERAL', N'Saving fails with an error', N'The message says why; usually a required field, a rule (approval, duplicate) or a lost connection.', N'', N'error save failed cannot save unexpected', N'{"steps": ["Read the message and fill / correct the highlighted fields.", "If it mentions approval, wait for the approver or ask them in Approval Dashboard.", "If it says the server could not be reached, check the connection and try again - do not create the record twice.", "Refresh the page and retry; if it repeats, note the time and tell the administrator (Audit Log helps)."], "prereq": [], "tips": [], "next": []}', 970);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('TS.SCAN.FAILED', 'TROUBLE', 'LAB', N'Smart ID Scan could not read the document', N'Blurred, cropped or very small images and unsupported documents cannot be read.', N'', N'smart id scan ocr not read aadhaar pan failed', N'{"steps": ["Use a clear, straight photo of the whole card in good light (or the original PDF).", "Supported: Aadhaar, PAN, passport. Other IDs can be uploaded but are not read.", "Check AI features are on for the branch (Hospital Settings).", "Type the details by hand if needed - the document is still attached."], "prereq": [], "tips": [], "next": []}', 980);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('TS.CAMPAIGN.FAILED', 'TROUBLE', 'UTILITY', N'Campaign emails failed', N'Failures come from the sending branch''s mail account or invalid addresses.', N'UTILITY.CAMPAIGNS,SETTINGS.SMTPCONFIG', N'campaign failed emails not delivered retry', N'{"steps": ["Open the campaign''s results, filter Failed and read the reason.", "Fix the branch''s Email Configuration (Test Email) and click Retry failed.", "Many failures at once may mean the provider''s sending limit - send to smaller groups or schedule."], "prereq": [], "tips": [], "next": []}', 990);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('TS.BARCODE', 'TROUBLE', 'LAB', N'The barcode label does not print or scan', N'Label printing depends on the printer settings and label size.', N'LAB.SAMPLECOLLECTION', N'barcode label print scan sticker', N'{"steps": ["Select the label printer and the correct label size in the print dialog; scale 100%.", "Print a test label; if bars are faint, clean / adjust the printer darkness.", "If a scanner does not read it, check the label is not wrinkled or covered by tape."], "prereq": [], "tips": [], "next": []}', 1000);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('TS.FRANCHISE.BALANCE', 'TROUBLE', 'LAB', N'B2B booking says the franchise has no balance', N'Prepaid franchises need wallet balance for each booking.', N'UTILITY.FRANCHISETOPUP,MASTER.LABFRANCHISES', N'franchise balance wallet insufficient b2b', N'{"steps": ["Top up the wallet in Utility > Franchise Top-Up (it may need approval).", "Check the franchise''s credit settings in Franchise Setup.", "Reports > LAB > Franchise Wallet Statement shows the balance and movements."], "prereq": [], "tips": [], "next": []}', 1010);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('TS.LICENCE', 'TROUBLE', 'SETTINGS', N'The sign-in screen asks for the licence', N'The server''s licence must be valid before anyone can sign in.', N'SETTINGS.LICENSE', N'licence license expired invalid sign in blocked', N'{"steps": ["Click Re-validate licence with the licence server and follow the steps (an OTP may be sent).", "Check the server has internet access to the licence server.", "If it still fails, contact your vendor with the message shown."], "prereq": [], "tips": [], "next": []}', 1020);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('TS.NO.TOKEN.SLOT', 'TROUBLE', 'OPD', N'No slots are available for a doctor', N'Slots come from the doctor''s roster for that day.', N'OPD.DOCTORROSTER', N'no slot doctor not available appointment roster', N'{"steps": ["Check OPD > Doctor Roster has the day and time for the doctor and the branch.", "Check leaves / holidays and that the slots are not already full.", "Check the doctor is active and assigned to the branch."], "prereq": [], "tips": [], "next": []}', 1030);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('TS.REPORT.EMPTY', 'TROUBLE', 'REPORTS', N'A report shows no data', N'The filters exclude everything, or the period has no records for your branch.', N'', N'report empty no data blank zero', N'{"steps": ["Widen the date range and clear filters, then Apply again.", "Check the branch (Head Office can choose a branch).", "Some reports use the bill date, others the collection or approval date - read the label of the date filter."], "prereq": [], "tips": [], "next": []}', 1040);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('FLOW.LAB.B2C', 'FLOW', 'LAB', N'LAB walk-in patient (B2C): from bill to report', N'A walk-in patient''s tests from the bill to the delivered report and the day''s cash closing.', N'LAB.LABORDERBOOKING.B2CBOOKING,LAB.SAMPLECOLLECTION,LAB.SAMPLETRANSFER,LAB.LABREPORTING,LAB.PATHOLOGISTDASHBOARD,LAB.LABREPORTDISPATCH,LAB.LABORDERBOOKING.B2CORDERLIST,LAB.DAYCLOSING', N'b2c walk in lab bill billing booking sample report', N'{"flow": [{"page": "LAB.LABORDERBOOKING.B2CBOOKING", "title": "Create the B2C bill", "do": "Find or register the patient, add tests / profiles / packages, take payment and print the bill.", "article": "LAB.B2C", "optional": false, "when": null}, {"page": "LAB.SAMPLECOLLECTION", "title": "Collect the sample", "do": "Find the bill, print the barcode labels, stick them on the tubes and click Collect.", "article": "LAB.COLLECT", "optional": false, "when": null}, {"page": "LAB.SAMPLETRANSFER", "title": "Send the sample to the testing branch", "do": "Transfer the collected samples; the other branch receives them.", "article": "LAB.TRANSFER", "optional": true, "when": "only when another branch runs the test"}, {"page": "LAB.LABREPORTING", "title": "Enter and validate the results", "do": "Open the bill in Lab Reporting Entry, type the results, Submit; a senior validates.", "article": "LAB.REPORT", "optional": false, "when": null}, {"page": "LAB.PATHOLOGISTDASHBOARD", "title": "Pathologist approves the report", "do": "The pathologist checks and approves (sign-off levels as set in Lab Approval Flows).", "article": "LAB.APPROVE", "optional": false, "when": null}, {"page": "LAB.LABREPORTDISPATCH", "title": "Deliver the report", "do": "Print the approved report or send it by email / WhatsApp.", "article": "LAB.DISPATCH", "optional": false, "when": null}, {"page": "LAB.LABORDERBOOKING.B2CORDERLIST", "title": "Collect the balance due", "do": "Open the bill in B2C Order List > Collect Payment and take the balance; a money receipt is printed.", "article": "LAB.DUE", "optional": true, "when": "only when the bill has a due amount"}, {"page": "LAB.DAYCLOSING", "title": "Close the day", "do": "At the end of the day submit the LAB Day Closing; a supervisor verifies it.", "article": "LAB.CLOSE", "optional": false, "when": null}], "primary": true, "steps": ["Create the B2C bill: Find or register the patient, add tests / profiles / packages, take payment and print the bill.", "Collect the sample: Find the bill, print the barcode labels, stick them on the tubes and click Collect.", "Send the sample to the testing branch (only when another branch runs the test): Transfer the collected samples; the other branch receives them.", "Enter and validate the results: Open the bill in Lab Reporting Entry, type the results, Submit; a senior validates.", "Pathologist approves the report: The pathologist checks and approves (sign-off levels as set in Lab Approval Flows).", "Deliver the report: Print the approved report or send it by email / WhatsApp.", "Collect the balance due (only when the bill has a due amount): Open the bill in B2C Order List > Collect Payment and take the balance; a money receipt is printed.", "Close the day: At the end of the day submit the LAB Day Closing; a supervisor verifies it."]}', 5000);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('FLOW.LAB.B2B', 'FLOW', 'LAB', N'LAB franchise / corporate (B2B): from booking to settlement', N'Tests booked for a franchise, collection centre or corporate, from the wallet to the invoice and settlement.', N'UTILITY.FRANCHISETOPUP,LAB.LABORDERBOOKING.B2BBOOKING,LAB.SAMPLECOLLECTION,LAB.SAMPLETRANSFER,LAB.LABREPORTING,LAB.PATHOLOGISTDASHBOARD,LAB.LABREPORTDISPATCH,LAB.LABORDERBOOKING.B2BINVOICES,LAB.LABORDERBOOKING.B2BSETTLEMENT', N'b2b franchise corporate partner collection centre booking invoice settlement', N'{"flow": [{"page": "UTILITY.FRANCHISETOPUP", "title": "Make sure the partner has balance", "do": "Top up the franchise wallet (prepaid franchises).", "article": "UT.FRANCHISE", "optional": true, "when": "only for prepaid franchises"}, {"page": "LAB.LABORDERBOOKING.B2BBOOKING", "title": "Create the B2B booking", "do": "Choose the partner, add the patient and tests on the partner''s rates, and save.", "article": "LAB.B2B", "optional": false, "when": null}, {"page": "LAB.SAMPLECOLLECTION", "title": "Collect / receive the sample", "do": "Print barcodes and mark the samples collected.", "article": "LAB.COLLECT", "optional": false, "when": null}, {"page": "LAB.SAMPLETRANSFER", "title": "Send the sample to the testing branch", "do": "Transfer and receive the samples.", "article": "LAB.TRANSFER", "optional": true, "when": "only when another branch runs the test"}, {"page": "LAB.LABREPORTING", "title": "Enter and validate the results", "do": "Type the results in Lab Reporting Entry and Submit; a senior validates.", "article": "LAB.REPORT", "optional": false, "when": null}, {"page": "LAB.PATHOLOGISTDASHBOARD", "title": "Pathologist approves the report", "do": "Sign off the report.", "article": "LAB.APPROVE", "optional": false, "when": null}, {"page": "LAB.LABREPORTDISPATCH", "title": "Deliver the report", "do": "Print, email or WhatsApp the report to the partner / patient.", "article": "LAB.DISPATCH", "optional": false, "when": null}, {"page": "LAB.LABORDERBOOKING.B2BINVOICES", "title": "Invoice the partner", "do": "Raise the partner''s invoice for the period.", "article": "LAB.B2B", "optional": false, "when": null}, {"page": "LAB.LABORDERBOOKING.B2BSETTLEMENT", "title": "Settle the partner''s payment", "do": "Record the partner''s payment against one or many bills.", "article": "LAB.B2B", "optional": false, "when": null}], "primary": false, "steps": ["Make sure the partner has balance (only for prepaid franchises): Top up the franchise wallet (prepaid franchises).", "Create the B2B booking: Choose the partner, add the patient and tests on the partner''s rates, and save.", "Collect / receive the sample: Print barcodes and mark the samples collected.", "Send the sample to the testing branch (only when another branch runs the test): Transfer and receive the samples.", "Enter and validate the results: Type the results in Lab Reporting Entry and Submit; a senior validates.", "Pathologist approves the report: Sign off the report.", "Deliver the report: Print, email or WhatsApp the report to the partner / patient.", "Invoice the partner: Raise the partner''s invoice for the period.", "Settle the partner''s payment: Record the partner''s payment against one or many bills."]}', 5010);
INSERT dbo.HelpArticle (Code, Kind, Module, Title, Summary, PageCodes, Keywords, BodyJson, SortOrder) VALUES ('FLOW.LAB.CORRECT', 'FLOW', 'LAB', N'Correct an approved LAB report (Re-Test / Re-Collect)', N'What happens after a report is un-authorised, until the revised report reaches the patient.', N'LAB.LABUNAPPROVE,LAB.SAMPLECOLLECTION,LAB.LABREPORTING,LAB.PATHOLOGISTDASHBOARD,LAB.LABREPORTDISPATCH', N'unapprove unauthorize retest re-test recollect re-collect correct amend revised report', N'{"flow": [{"page": "LAB.LABUNAPPROVE", "title": "Un-authorise the report", "do": "Choose the tests, Re-Test or Re-Collect, and the reason.", "article": "LAB.UNAPPROVE", "optional": false, "when": null}, {"page": "LAB.SAMPLECOLLECTION", "title": "Collect a new sample", "do": "Collect the new sample and print its barcode.", "article": "LAB.COLLECT", "optional": true, "when": "only for Re-Collect"}, {"page": "LAB.LABREPORTING", "title": "Enter the corrected results", "do": "Correct the results and Submit; a senior validates.", "article": "LAB.REPORT", "optional": false, "when": null}, {"page": "LAB.PATHOLOGISTDASHBOARD", "title": "Approve again", "do": "The pathologist approves the corrected report.", "article": "LAB.APPROVE", "optional": false, "when": null}, {"page": "LAB.LABREPORTDISPATCH", "title": "Send the revised report", "do": "Deliver the report; it is marked as revised.", "article": "LAB.DISPATCH", "optional": false, "when": null}], "primary": false, "steps": ["Un-authorise the report: Choose the tests, Re-Test or Re-Collect, and the reason.", "Collect a new sample (only for Re-Collect): Collect the new sample and print its barcode.", "Enter the corrected results: Correct the results and Submit; a senior validates.", "Approve again: The pathologist approves the corrected report.", "Send the revised report: Deliver the report; it is marked as revised."]}', 5020);
